  "implementation": "def solve(case):
    import json

    # Validate basic structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("case must have 'nodes' (list) and 'required_symbols' (list)")

    node_map = {}
    parent_to_children = {}
    for nd in nodes:
        if not isinstance(nd, dict):
            raise ValueError("each node must be a dict")
        nid = nd.get('id')
        parent = nd.get('parent')
        symbol = nd.get('symbol')
        depth = nd.get('depth')
        removable = nd.get('removable')
        if not all(k in nd for k in ('id','parent','symbol','depth','removable')):
            raise ValueError("node missing required field")
        node_map[nid] = nd
        if parent is not None:
            parent_to_children.setdefault(parent, []).append(nid)
        else:
            # root should have no parent
            pass

    # Build list of removable candidate ids (exclude root)
    candidates = []
    for nid, nd in node_map.items():
        if nd.get('removable') is True:
            # also exclude nodes whose symbol is in required_symbols? We'll check condition later
            candidates.append(nid)

    # Sort by depth descending, then by id string (tie-breaker)
    def sort_key(nid):
        nd = node_map[nid]
        return (-nd['depth'], nid)
    candidates.sort(key=sort_key)

    retained = set(node_map.keys())
    removed = []

    for cid in candidates:
        nd = node_map[cid]
        # cannot remove if any child is still retained
        children = parent_to_children.get(cid, [])
        if any(ch in retained for ch in children):
            continue

        # tentatively remove
        temp_retained = retained - {cid}
        # check each required symbol still present
        all_symbols = {node_map[nid]['symbol'] for nid in temp_retained}
        if all(sym in all_symbols for sym in required_symbols):
            # also ensure we don't remove a node whose symbol is required? Let's check:
            # The instruction "Never remove ... a required symbol" might mean never remove a node
            # whose symbol is in required_symbols. We'll respect that if the node's symbol is required
            # and it's the only one with that symbol? Actually to be safe, we only allow removal
            # if after removal the required symbol is still there. That covers the intent.
            # But strictly: never remove a node that is itself a required symbol.
            # However, if the node's symbol is required and it's the only one, then removal would fail
            # the all_symbols check. So we are fine.
            # So proceed with removal.
            removed.append(cid)
            retained = temp_retained

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }
